  getContrastInfo(skuId) {
    const DOM = $('.J-product-contrast')

    let params = {
      shopifyShopId: shopId,
      skuId: skuId
    }
    productContrast(params).then(res => {
      if (res.code === 200 && res.data.haveCompareInfo) {
        let html = this.creatContrastDom(res.data)
        DOM.find('.contrast-wrap').html(html)
        DOM.show()
        this.essential(DOM.find(".J-select-product"), res.data)
      } else {
        DOM.find('.contrast-wrap').empty()
        DOM.hide()
      }
    })
  }
  creatContrastDom(res) {
    let mainInfos = '', compareOneInfos = '', compareTwoInfos = ''
    res.main.compareInfos && res.main.compareInfos.map(item => {
      mainInfos += `<span>${item}</span>`
    })
    res.compareOne.compareInfos && res.compareOne.compareInfos.map(n => {
      compareOneInfos += `<span>${n}</span>`
    })
    res.compareTwo.compareInfos && res.compareTwo.compareInfos.map(v => {
      compareTwoInfos += `<span>${v}</span>`
    })
    let main = `
      <li class="contrast-product main-pdt">
        <img src="${res.main.image}" alt="">
        <div class="flex flex-col" style="flex:1;justify-content:flex-start;">
          <div class="name">${res.main.title}</div>
          <div class="param jky-text-base ${mainInfos === '' ? 'display-none' : ''}">
            ${mainInfos}
          </div>
        </div>
      </li>
    `;
    let ids = res.compareTwo.skuId ? [res.compareOne.skuId, res.compareTwo.skuId] : [res.compareOne.skuId]
    let selectDomOne = this.creatSelectDom(res.all, res.compareOne.skuId, ids)
    let selectDomTwo = this.creatSelectDom(res.all, res.compareTwo.skuId, ids)
    let compareOne = `
      <li class="contrast-product" data-index="compareOne">
        <select class="select-product J-select-product" value="${res.compareOne.skuId}">
          ${selectDomOne}
        </select>
        <img src="${res.compareOne.image}" alt="">
        <div class="flex flex-col" style="flex:1;justify-content:space-between;">
          <div class="name">
            <a class="text-inherit" href="${window.location.origin + '/products/' + res.compareOne.handle}">${res.compareOne.title}</a>
          </div>
          <div class="param jky-text-base ${compareOneInfos === '' ? 'display-none' : ''}">
            ${compareOneInfos}
          </div>
          <div class="more">
            <a class="z-button-fill-middle" href="${window.location.origin + '/products/' + res.compareOne.handle}" data-analytics-title="${res.compareOne.title}">
              <span>${window.page_productStrings.viewMore}</span>
              <i class="iconfont jackery-icon-arrow-right"></i>
            </a>
          </div>
        </div>
      </li>
    `;
    let compareTwo = '';
    if (res.compareTwo.gid) {
      compareTwo = `
        <li class="contrast-product" data-index="compareTwo">
          <select class="select-product J-select-product" value="${res.compareTwo.skuId}">
            ${selectDomTwo}
          </select>
          <img src="${res.compareTwo.image}" alt="">
          <div class="flex flex-col" style="flex:1;justify-content:space-between;">
            <div class="name">
              <a class="text-inherit" href="${window.location.origin + '/products/' + res.compareTwo.handle}">${res.compareTwo.title}</a>
            </div>
            <div class="param jky-text-base ${compareTwoInfos === '' ? 'display-none' : ''}">
              ${compareTwoInfos}
            </div>
            <div class="more">
              <a class="z-button-fill-middle" href="${window.location.origin + '/products/' + res.compareTwo.handle}" data-analytics-title="${res.compareTwo.title}">
                <span>${window.page_productStrings.viewMore}</span>
                <i class="iconfont jackery-icon-arrow-right"></i>
              </a>
            </div>
          </div>
        </li>
      `
    }
    let html = main + compareOne + compareTwo
    return html
  }
  creatSelectDom(data, skuId, ids) {
    let options = ''
    if (data) {
      data.map(item => {
        options += `
          <option ${item.skuId === skuId ? 'selected' : ''} ${ids.indexOf(item.skuId) !== -1 ? 'disabled' : ''} value="${item.skuId}">${item.title}</option>
        `
      })
    }
    return options
  }
  changeSelectDom(item, res, el) {

    let infos = ''
    let index = el.parent('.contrast-product').data('index') === 'compareTwo' ? 1 : 0
    const DOM = $('.J-product-contrast')
    item.compareInfos && item.compareInfos.map(n => {
      infos += `<span>${n}</span>`
    })
    let ids = [item.skuId], otherSelectId = ''
    if (index === 1) {
      ids.push(DOM.find(".J-select-product").eq(0).attr('value'))
      otherSelectId = DOM.find(".J-select-product").eq(0).attr('value')
    } else {
      DOM.find(".J-select-product").eq(1).attr('value') ? ids.push(DOM.find(".J-select-product").eq(1).attr('value')) : ''
      otherSelectId = DOM.find(".J-select-product").eq(1).attr('value')
    }
    let selectDom = this.creatSelectDom(res.all, item.skuId, ids)
    let html = `
      <select class="select-product J-select-product" value="${item.skuId}">
        ${selectDom}
      </select>
      <img src="${item.image}" alt="">
      <div class="flex flex-col" style="flex:1;justify-content:space-between;">
        <div class="name">${item.title}</div>
        <div class="param jky-text-base ${infos === '' ? 'display-none' : ''}">
          ${infos}
        </div>
        <div class="more">
          <a class="z-button-fill-middle" href="${window.location.origin + '/products/' + item.handle}">
            <span>${window.page_productStrings.viewMore}</span>
            <i class="iconfont jackery-icon-arrow-right"></i>
          </a>
        </div>
      </div>
    `;

    if (otherSelectId) {
      // const other_options = el.parent('.contrast-product').siblings('.contrast-product').find('.J-select-product option')
      // el.parent('.contrast-product').siblings('.contrast-product').find('.J-select-product')

      // FIX: 更新对应的option属性即可
      el.parent('.contrast-product').siblings('.contrast-product').find('.J-select-product option').each((_, item) => {
        const __r = ids.filter(i => $(item).attr("value") == i)
        if(__r.length > 0) {
          $(item).attr("disabled", "true")
        } else {
          $(item).removeAttr("disabled")
        }
      })


      // let otherSelectDom = this.creatSelectDom(res.all, otherSelectId, ids)
      // el.parent('.contrast-product').siblings('.contrast-product').find('.J-select-product').empty().html(otherSelectDom)
    }
    el.parent('.contrast-product').empty().html(html)
    this.essential(DOM.find(".J-select-product"), res)
  }
  getSpecsInfo(skuId) {
    const DOM = $('.J-specs-box')
    if(DOM.hasClass("J-specs-box--hide")) return
    let params = {
      shopifyShopId: shopId,
      skuId: skuId
    }
    productBaseInfo(params).then(res => {
      let data = res.data;
      if (data) {
        let dom = this.creatSpecsDom(data)
        DOM.find('.content').html(dom)
        DOM.show()
        this.slideToggle(DOM.find('.content'))
      } else {
        DOM.find('.content').empty()
        DOM.hide()
      }
    })
  }
  creatSpecsItemDom(obj) {
    let html = ''
    for (let n in obj) {
      if (typeof(obj[n]) === 'string') {
        html += `
          <div class="specs-item">
            <span class="key">${n}${obj[n]? ':' : ''}</span>
            <span class="value">${replaceLineBreak(obj[n])}</span>
          </div>
        `
      } else {
        html += this.creatSpecsItemDom(obj[n])
      }
    }
    return html
  }
